 13		"github.com/navidrome/navidrome/utils/singleton"
 14		"github.com/pressly/goose/v3"
 15	)
 16	
 17	var (
 18		Driver = "sqlite3"
 19		Path   string
 20	)
 21	
 22	//go:embed migrations/*.sql
 23	var embedMigrations embed.FS
 24	
 25	const migrationsFolder = "migrations"
 26	
 27	func Db() *sql.DB {
 28		return singleton.GetInstance(func() *sql.DB {
 29			sql.Register(Driver+"_custom", &sqlite3.SQLiteDriver{
 30				ConnectHook: func(conn *sqlite3.SQLiteConn) error {
 31					return conn.RegisterFunc("SEEDEDRAND", hasher.HashFunc(), false)
 32				},
 33			})
 34	
 35			Path = conf.Server.DbPath
 36			if Path == ":memory:" {
 37				Path = "file::memory:?cache=shared&_foreign_keys=on"
 38				conf.Server.DbPath = Path
 39			}
 40			log.Debug("Opening DataBase", "dbPath", Path, "driver", Driver)
 41			instance, err := sql.Open(Driver+"_custom", Path)
 42			if err != nil {
 43				panic(err)
 44			}
 45			return instance
 46		})
 47	}
 48	
 49	func Close() error {
 50		log.Info("Closing Database")
 51		return Db().Close()
 52	}
 53	
 54	func Init() func() {
 55		db := Db()
 56	
 57		// Disable foreign_keys to allow re-creating tables in migrations
 58		_, err := db.Exec("PRAGMA foreign_keys=off")
 59		defer func() {
 60			_, err := db.Exec("PRAGMA foreign_keys=on")
 61			if err != nil {
 62				log.Error("Error re-enabling foreign_keys", err)
 63			}
 64		}()
 65		if err != nil {
 66			log.Error("Error disabling foreign_keys", err)
 67		}
 68	
 69		gooseLogger := &logAdapter{silent: isSchemaEmpty(db)}
 70		goose.SetBaseFS(embedMigrations)
 71	
 72		err = goose.SetDialect(Driver)
 73		if err != nil {
 74			log.Fatal("Invalid DB driver", "driver", Driver, err)
 75		}
 76		if !isSchemaEmpty(db) && hasPendingMigrations(db, migrationsFolder) {
 77			log.Info("Upgrading DB Schema to latest version")
 78		}
 79		goose.SetLogger(gooseLogger)
 80		err = goose.Up(db, migrationsFolder)
 81		if err != nil {
 82			log.Fatal("Failed to apply new migrations", err)
 83		}
 84	
 85		return func() {
 86			if err := Close(); err != nil {
 87				log.Error("Error closing DB", err)
 88			}
 89		}
 90	}
