 92	type statusLogger struct{ numPending int }
 93	
 94	func (*statusLogger) Fatalf(format string, v ...interface{}) { log.Fatal(fmt.Sprintf(format, v...)) }
 95	func (l *statusLogger) Printf(format string, v ...interface{}) {
 96		if len(v) < 1 {
 97			return
 98		}
 99		if v0, ok := v[0].(string); !ok {
100			return
101		} else if v0 == "Pending" {
102			l.numPending++
103		}
104	}
105	
106	func hasPendingMigrations(db *sql.DB, folder string) bool {
107		l := &statusLogger{}
108		goose.SetLogger(l)
109		err := goose.Status(db, folder)
110		if err != nil {
111			log.Fatal("Failed to check for pending migrations", err)
112		}
113		return l.numPending > 0
114	}
