116	func isSchemaEmpty(db *sql.DB) bool {
117		rows, err := db.Query("SELECT name FROM sqlite_master WHERE type='table' AND name='goose_db_version';") // nolint:rowserrcheck
118		if err != nil {
119			log.Fatal("Database could not be opened!", err)
120		}
121		defer rows.Close()
122		return !rows.Next()
123	}
