109	func (s *SQLStore) WithTx(block func(tx model.DataStore) error) error {
110		conn, ok := s.db.(*dbx.DB)
111		if !ok {
112			conn = dbx.NewFromDB(db.Db(), db.Driver)
113		}
114		return conn.Transactional(func(tx *dbx.Tx) error {
115			newDb := &SQLStore{db: tx}
116			return block(newDb)
117		})
118	}
