120	func (s *SQLStore) GC(ctx context.Context, rootFolder string) error {
121		err := s.MediaFile(ctx).(*mediaFileRepository).deleteNotInPath(rootFolder)
122		if err != nil {
123			log.Error(ctx, "Error removing dangling tracks", err)
124			return err
125		}
126		err = s.MediaFile(ctx).(*mediaFileRepository).removeNonAlbumArtistIds()
127		if err != nil {
128			log.Error(ctx, "Error removing non-album artist_ids", err)
129			return err
130		}
131		err = s.Album(ctx).(*albumRepository).purgeEmpty()
132		if err != nil {
133			log.Error(ctx, "Error removing empty albums", err)
134			return err
135		}
136		err = s.Artist(ctx).(*artistRepository).purgeEmpty()
137		if err != nil {
138			log.Error(ctx, "Error removing empty artists", err)
139			return err
140		}
141		err = s.MediaFile(ctx).(*mediaFileRepository).cleanAnnotations()
142		if err != nil {
143			log.Error(ctx, "Error removing orphan mediafile annotations", err)
144			return err
145		}
146		err = s.Album(ctx).(*albumRepository).cleanAnnotations()
147		if err != nil {
148			log.Error(ctx, "Error removing orphan album annotations", err)
149			return err
150		}
151		err = s.Artist(ctx).(*artistRepository).cleanAnnotations()
152		if err != nil {
153			log.Error(ctx, "Error removing orphan artist annotations", err)
154			return err
155		}
156		err = s.MediaFile(ctx).(*mediaFileRepository).cleanBookmarks()
157		if err != nil {
158			log.Error(ctx, "Error removing orphan bookmarks", err)
159			return err
160		}
161		err = s.Playlist(ctx).(*playlistRepository).removeOrphans()
162		if err != nil {
163			log.Error(ctx, "Error tidying up playlists", err)
164		}
165		err = s.Genre(ctx).(*genreRepository).purgeEmpty()
166		if err != nil {
167			log.Error(ctx, "Error removing unused genres", err)
168			return err
169		}
170		return err
171	}
